'use strict';
const wallpapers=[['paper','旧书纸页'],['stars','午夜星图'],['sage','鼠尾草格纹'],['rose','蔷薇手笺'],['blue','雾蓝信纸'],['sand','暖砂细纹']];
let mapId=null,linkMode=false,linkStart=null,zoom=1;
const oldValid=valid;valid=function(d){return oldValid(d)&&(!d.settings||(typeof d.settings==='object'&&(!d.settings.wallpaper||wallpapers.some(([k])=>k===d.settings.wallpaper)||d.settings.wallpaper==='custom')&&(!d.settings.custom||imageOK(d.settings.custom))))&&(!d.maps||(Array.isArray(d.maps)&&new Set(d.maps.map(m=>m.id)).size===d.maps.length&&d.maps.every(m=>typeof m.id==='string'&&typeof m.name==='string'&&Array.isArray(m.nodes)&&new Set(m.nodes.map(n=>n.id)).size===m.nodes.length&&m.nodes.every(n=>d.characters.some(c=>c.id===n.id)&&Number.isFinite(n.x)&&Number.isFinite(n.y)))))&&d.relations.every(r=>!r.direction||['forward','both','none'].includes(r.direction))};
function applyWallpaper(){const s=data.settings||{},custom=s.wallpaper==='custom'&&imageOK(s.custom);document.documentElement.style.setProperty('--veil',String(s.opacity??0.72));document.body.dataset.wallpaper=custom?'custom':s.wallpaper==='custom'?'paper':s.wallpaper||'paper';document.body.style.backgroundImage='';let backdrop=$('towerBackdrop');if(!backdrop){backdrop=document.createElement('div');backdrop.id='towerBackdrop';backdrop.setAttribute('aria-hidden','true');document.body.prepend(backdrop)}backdrop.style.backgroundImage=custom?'url("'+s.custom+'")':'';const status=$('wallpaperStatus');if(status)status.textContent=custom?'正在使用自定义壁纸':'正在使用主题背景 / 内置壁纸';const preview=$('currentWallpaper');if(preview){preview.hidden=!custom;if(custom)preview.src=s.custom;else preview.removeAttribute('src')}}
$('wallpaper').onclick=()=>{if(!ready)return;modal('<h2>塔外的风景</h2><p class="hint">壁纸会等比例覆盖整个窗口，不重复。调高玻璃厚度，面板更实、文字更清楚。</p><label class="field">雾玻璃厚度 <output id="opacityValue"></output><input type="range" id="wallOpacity" min="0" max="100" aria-label="雾玻璃厚度"></label><div class="wallChoices">'+wallpapers.map(([k,n])=>`<button class="wallChoice" data-wall="${k}" data-wallpaper="${k}">${n}${(data.settings?.wallpaper||'paper')===k?' ✓':''}</button>`).join('')+'</div><label class="field">或上传自己的壁纸<input type="file" id="customWallpaper" accept="image/png,image/jpeg,image/webp,image/gif"></label><p class="hint" id="wallpaperStatus"></p><img id="currentWallpaper" class="wallpaperPreview" alt="当前自定义壁纸预览" hidden><div class="wallpaperReset"><button type="button" id="resetWallpaper">恢复主题默认背景</button><span class="hint">去除自定义壁纸，保留当前主题与所有记录。</span></div><div class="dialogActions"><button data-action="close">完成</button></div>');$('resetWallpaper').onclick=async()=>{if(busy)return;const next=clone();next.settings={...(next.settings||{})};delete next.settings.wallpaper;delete next.settings.custom;delete next.settings.opacity;busy=true;try{if(await commit(next)){$('wallOpacity').value=72;$('opacityValue').value='72%';toast('已去除壁纸，恢复当前主题背景。')}}finally{busy=false}};applyWallpaper();$('customWallpaper').onchange=async()=>{try{const f=$('customWallpaper').files[0];if(!f)return;const custom=await readImage(f),next=clone();next.settings={...(next.settings||{}),wallpaper:'custom',custom};if(await commit(next)){$('dialog').close();toast('自定义壁纸已保存。')}}catch(e){toast(e.message)}}};
function removeProfile(next,type,id){const removed=type==='game'?next.characters.filter(c=>c.gameId===id).map(c=>c.id):[id];if(type==='game')next.games=next.games.filter(g=>g.id!==id);next.characters=next.characters.filter(c=>!removed.includes(c.id));next.relations=next.relations.filter(r=>!removed.includes(r.a)&&!removed.includes(r.b));next.posts.forEach(p=>{if(type==='game')p.games=p.games.filter(g=>g!==id);p.characters=p.characters.filter(c=>!removed.includes(c))});(next.maps||[]).forEach(m=>m.nodes=m.nodes.filter(n=>!removed.includes(n.id)));return next}
function deleteProfile(){const type=view.type,id=view.id,x=type==='game'?game(id):character(id),count=type==='game'?data.characters.filter(c=>c.gameId===id).length:0;modal(`<h2>删除「${esc(x.name)}」？</h2><p>${type==='game'?`此档案及其 ${count} 个角色将被删除。`:'此角色将被删除。'}相关关系连线、图中节点和帖子关联会移除。</p><p><strong>帖子正文、图片、收藏和草稿都会保留。</strong>删除无法撤销，可先导出备份。</p><div class="dialogActions"><button data-action="close">取消</button><button class="primary" id="deleteProfileConfirm">确认删除</button></div>`);$('deleteProfileConfirm').onclick=async()=>{const oldView=view;view={type:'all',id:null};if(await commit(removeProfile(clone(),type,id))){combo=combo.filter(c=>character(c));$('dialog').close();toast('已删除，帖子内容已保留。')}else view=oldView}}
const baseProfile=renderProfile,baseFeed=renderFeed,baseFilters=renderFilters;
renderProfile=function(){if(view.type!=='graph')return baseProfile();$('profile').innerHTML='<p class="eyebrow">CONSTELLATIONS / 角色关系图</p><h1>让彼此相连</h1><p class="muted">可自由设置</p>'};
renderFilters=function(){if(view.type==='graph'){$('filters').innerHTML='';return}baseFilters()};
function currentMap(){const maps=data.maps||[];return maps.find(m=>m.id===mapId)||maps[0]}
renderFeed=function(){if(view.type!=='graph')return baseFeed();const maps=data.maps||[],m=currentMap();mapId=m?.id||null;$('feed').innerHTML=`<div class="row mapTools"><select id="mapSelect" aria-label="选择关系图" style="width:auto"><option value="">${maps.length?'选择关系图':'尚无关系图'}</option>${maps.map(x=>`<option value="${esc(x.id)}" ${x.id===mapId?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button data-graph="new">＋ 新建关系图</button>${m?'<button data-graph="rename">重命名</button><button data-graph="members">添加 / 移除角色</button><button data-graph="link" class="'+(linkMode?'active':'')+'">'+(linkMode?'结束连线':'连接角色')+'</button><button data-graph="export">导出图片 SVG</button><button class="danger" data-graph="delete">删除此图</button>':''}</div>${m?`<p class="hint" id="graphHint">${linkMode?'从起点头像拖到终点头像连线，或依次点击两个角色。':'拖动头像自由摆放，松手自动保存。点击连线文字可编辑关系；方向键可微调选中的角色。'}</p><div class="row"><button data-graph="out" aria-label="缩小">−</button><span id="zoomLabel">${Math.round(zoom*100)}%</span><button data-graph="in" aria-label="放大">＋</button><button data-graph="reset">重置缩放</button></div><div class="graphScroll"><svg id="graphSvg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 700" role="group" aria-label="${esc(m.name)}角色关系图"></svg></div>`:'<div class="empty">建立一张关系图，把不同档案里的角色放在同一片星空下。</div>'}`;if(m){drawGraph();bindGraph();$('mapSelect').onchange=()=>{mapId=$('mapSelect').value;zoom=1;linkStart=null;renderFeed()}}};
function edgeGeometry(a,b,index,total){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len;const shift=(index-(total-1)/2)*42;const cx=(a.x+b.x)/2-uy*shift*2,cy=(a.y+b.y)/2+ux*shift*2;const startAngle=Math.atan2(cy-a.y,cx-a.x),endAngle=Math.atan2(b.y-cy,b.x-cx);const sx=a.x+Math.cos(startAngle)*43,sy=a.y+Math.sin(startAngle)*43,ex=b.x-Math.cos(endAngle)*48,ey=b.y-Math.sin(endAngle)*48;return {path:`M ${sx} ${sy} Q ${cx} ${cy} ${ex} ${ey}`,x:(sx+2*cx+ex)/4,y:(sy+2*cy+ey)/4}}
function drawGraph(){const m=currentMap(),svg=$('graphSvg');if(!m||!svg)return;svg.style.width=`${zoom*100}%`;svg.style.minWidth=`${zoom*650}px`;const nodes=m.nodes,rels=data.relations.filter(r=>nodes.some(n=>n.id===r.a)&&nodes.some(n=>n.id===r.b));let html='<defs><marker id="arrowEnd" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10" fill="none" stroke="#655c50" stroke-width="1.5"/></marker></defs><rect width="1000" height="700" fill="#fcfaf4"/><text x="26" y="32" fill="#887d6e" font-size="14" font-family="serif">'+esc(m.name)+' · 观星塔</text>';rels.forEach(r=>{const a=nodes.find(n=>n.id===r.a),b=nodes.find(n=>n.id===r.b),group=rels.filter(x=>(x.a===r.a&&x.b===r.b)||(x.a===r.b&&x.b===r.a));const canonical=r.a<r.b,g=edgeGeometry(canonical?a:b,canonical?b:a,group.indexOf(r),group.length),dir=r.direction||'forward',color=/^#[0-9a-f]{6}$/i.test(r.color||'')?r.color:'#655c50',marker='arrow'+rels.indexOf(r);let path=g.path;if(!canonical){const reverse=edgeGeometry(a,b,group.length-1-group.indexOf(r),group.length);path=reverse.path}html+=`<defs><marker id="${marker}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10" fill="none" stroke="${color}" stroke-width="1.5"/></marker></defs><g data-edge="${esc(r.id)}" tabindex="0" role="button" aria-label="编辑 ${esc(character(r.a).name)} 到 ${esc(character(r.b).name)}：${esc(r.label)}"><path d="${path}" fill="none" stroke="transparent" stroke-width="18"/><path d="${path}" fill="none" stroke="${color}" stroke-width="1.6" ${dir!=='none'?`marker-end="url(#${marker})"`:''} ${dir==='both'?`marker-start="url(#${marker})"`:''}/><text x="${g.x}" y="${g.y-8}" text-anchor="middle" fill="${color}" stroke="#fcfaf4" stroke-width="7" paint-order="stroke" font-family="serif" font-size="14">${esc(r.label)}</text></g>`});nodes.forEach((n,i)=>{const c=character(n.id);html+=`<g data-node="${esc(n.id)}" transform="translate(${n.x},${n.y})" tabindex="0" role="button" aria-label="${esc(c.name)}，拖动或使用方向键移动"><circle r="39" fill="#f1e9df" stroke="${linkStart===n.id?'#884a3e':'#c8bcab'}" stroke-width="${linkStart===n.id?4:2}"/>${c.avatar?`<defs><clipPath id="clip${i}"><circle r="35"/></clipPath></defs><image href="${esc(c.avatar)}" x="-35" y="-35" width="70" height="70" preserveAspectRatio="xMidYMid slice" clip-path="url(#clip${i})"/>`:`<text text-anchor="middle" y="9" fill="#884a3e" font-family="serif" font-size="26">${esc(c.name.slice(0,1))}</text>`}<text y="60" text-anchor="middle" fill="#39372f" font-size="15" font-family="serif">${esc(c.name)}</text></g>`});if(!nodes.length)html+='<text x="500" y="350" text-anchor="middle" fill="#887d6e" font-size="18">点击「添加 / 移除角色」开始绘图</text>';svg.innerHTML=html}
function bindGraph(){const svg=$('graphSvg');let drag=null;const point=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())};let wire=null,suppressClick=false;svg.onpointerdown=e=>{const node=e.target.closest('[data-node]');if(!node)return;if(linkMode){wire={id:node.dataset.node,start:point(e),moved:false};svg.setPointerCapture(e.pointerId);return}e.preventDefault();const n=currentMap().nodes.find(n=>n.id===node.dataset.node),p=point(e);drag={id:n.id,dx:p.x-n.x,dy:p.y-n.y,x:n.x,y:n.y};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(wire){const p=point(e);wire.moved=Math.hypot(p.x-wire.start.x,p.y-wire.start.y)>8;drawGraph();if(wire.moved){const n=currentMap().nodes.find(n=>n.id===wire.id),line=document.createElementNS("http://www.w3.org/2000/svg","line");for(const [k,v] of Object.entries({x1:n.x,y1:n.y,x2:p.x,y2:p.y,stroke:"#884a3e","stroke-width":2,"stroke-dasharray":"6 5","pointer-events":"none"}))line.setAttribute(k,v);svg.appendChild(line)}return}if(!drag)return;const p=point(e),n=currentMap().nodes.find(n=>n.id===drag.id);n.x=Math.max(60,Math.min(940,p.x-drag.dx));n.y=Math.max(85,Math.min(610,p.y-drag.dy));drawGraph()};svg.onpointerup=async e=>{if(wire){const w=wire;wire=null;drawGraph();if(w.moved){suppressClick=true;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest("[data-node]");if(target&&target.dataset.node!==w.id){linkStart=null;openRelation();$("relationA").value=w.id;$("relationB").value=target.dataset.node}else toast("请把连线拖到另一个角色头像上。")}return}if(!drag)return;const d=drag;drag=null;const next=clone(),n=currentMap().nodes.find(n=>n.id===d.id);n.x=d.x;n.y=d.y;await commit(next)};svg.onpointercancel=()=>{wire=null;if(drag){const n=currentMap().nodes.find(n=>n.id===drag.id);n.x=drag.x;n.y=drag.y;drag=null;drawGraph()}};svg.onclick=e=>{if(suppressClick){suppressClick=false;return}const edge=e.target.closest('[data-edge]');if(edge)return openRelation(edge.dataset.edge);const node=e.target.closest('[data-node]');if(!linkMode||!node)return;if(!linkStart){linkStart=node.dataset.node;drawGraph();$('graphHint').textContent='已选起点，再点击另一个角色作为终点。'}else if(linkStart!==node.dataset.node){const a=linkStart,b=node.dataset.node;linkStart=null;drawGraph();openRelation();$('relationA').value=a;$('relationB').value=b}};svg.onkeydown=async e=>{const edge=e.target.closest('[data-edge]'),node=e.target.closest('[data-node]');if(e.key==='Enter'||e.key===' '){e.preventDefault();if(edge)openRelation(edge.dataset.edge);else if(node)node.dispatchEvent(new MouseEvent('click',{bubbles:true}));return}if(!node||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const next=clone(),n=next.maps.find(m=>m.id===mapId).nodes.find(n=>n.id===node.dataset.node);n.x=Math.max(60,Math.min(940,n.x+({'ArrowLeft':-10,'ArrowRight':10}[e.key]||0)));n.y=Math.max(85,Math.min(610,n.y+({'ArrowUp':-10,'ArrowDown':10}[e.key]||0)));const id=n.id;await commit(next);[...$('graphSvg').querySelectorAll('[data-node]')].find(x=>x.dataset.node===id)?.focus()}}
function mapMembers(){const m=currentMap();modal(`<form id="membersForm"><h2>图中的角色</h2><p class="hint">可跨档案选择。移出此图只移除节点，不删除角色、帖子或关系档案。</p><div class="checks">${checks('characters',m.nodes.map(n=>n.id))}</div>${endForm}`);$('membersForm').onsubmit=async e=>{e.preventDefault();const ids=[...$('membersForm').querySelectorAll('input:checked')].map(n=>n.value),next=clone(),target=next.maps.find(x=>x.id===m.id);target.nodes=ids.map((id,i)=>m.nodes.find(n=>n.id===id)||{id,x:500+Math.cos(i/Math.max(ids.length,1)*Math.PI*2-Math.PI/2)*260,y:350+Math.sin(i/Math.max(ids.length,1)*Math.PI*2-Math.PI/2)*220});if(await commit(next))$('dialog').close()}}
function mapName(edit=false){const m=currentMap();modal(`<form id="mapNameForm"><h2>${edit?'重命名':'新建'}关系图</h2><label class="field">名称<input type="text" id="mapName" maxlength="100" required value="${esc(edit?m.name:'')}"></label>${endForm}`);$('mapNameForm').onsubmit=async e=>{e.preventDefault();const name=$('mapName').value.trim();if(!name)return;const next=clone();next.maps??=[];if(edit)next.maps.find(x=>x.id===m.id).name=name;else{mapId=uid();next.maps.push({id:mapId,name,nodes:[]})}if(await commit(next)){$('dialog').close();if(!edit)mapMembers()}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.wall){const next=clone();next.settings={...(next.settings||{}),wallpaper:d.wall};if(await commit(next))toast('壁纸已切换。')}if(d.action==='deleteProfile')deleteProfile();if(!d.graph)return;const m=currentMap();if(d.graph==='new')mapName();if(d.graph==='rename')mapName(true);if(d.graph==='members')mapMembers();if(d.graph==='link'){linkMode=!linkMode;linkStart=null;renderFeed()}if(['in','out','reset'].includes(d.graph)){zoom=d.graph==='reset'?1:Math.min(2.5,Math.max(.6,zoom+(d.graph==='in'?.2:-.2)));drawGraph();$('zoomLabel').textContent=Math.round(zoom*100)+'%'}if(d.graph==='delete'){modal('<h2>删除这张关系图？</h2><p>只删除图与布局，角色、关系档案和帖子全部保留。</p><div class="dialogActions"><button data-action="close">取消</button><button class="primary" id="deleteMap">确认删除</button></div>');$('deleteMap').onclick=async()=>{const next=clone();next.maps=next.maps.filter(x=>x.id!==m.id);if(await commit(next))$('dialog').close()}}if(d.graph==='export'){const svg=$('graphSvg').cloneNode(true);svg.removeAttribute('style');svg.setAttribute('width','1000');svg.setAttribute('height','700');const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=m.name.replace(/[<>:"/\\|?*]/g,'_')+'-关系图.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
